svg.script:
var NS = 'http://www.w3.org/2000/svg';
var board = document.getElementById('board');
var statusEl = document.getElementById('status');
var scoreEl = document.getElementById('score');
var winline = document.getElementById('winline');
var LINES = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
var state, turn, over, cells = [], marks = [];
var score = { X: 0, O: 0, D: 0 };
function make(name, attrs) {
  var e = document.createElementNS(NS, name);
  for (var k in attrs) e.setAttribute(k, attrs[k]);
  return e;
}
function center(i) {
  return [30 + (i % 3) * 142 + 68, 150 + Math.floor(i / 3) * 142 + 68];
}
for (var i = 0; i < 9; i++) {
  (function (i) {
    var x = 30 + (i % 3) * 142, y = 150 + Math.floor(i / 3) * 142;
    var r = make('rect', { id: 'c' + i, x: x, y: y, width: 136, height: 136, rx: 12, fill: '#1e293b', stroke: '#334155', 'stroke-width': 1.5, cursor: 'pointer' });
    var t = make('text', { x: x + 68, y: y + 68, 'text-anchor': 'middle', 'dominant-baseline': 'central', 'font-size': 72, 'font-weight': 'bold', 'pointer-events': 'none', fill: 'transparent' });
    r.addEventListener('click', function () { place(i); });
    r.addEventListener('mouseenter', function () { if (!over && !state[i]) r.setAttribute('fill', '#273449'); });
    r.addEventListener('mouseleave', function () { if (!state[i]) r.setAttribute('fill', '#1e293b'); });
    board.appendChild(r); board.appendChild(t);
    cells.push(r); marks.push(t);
  })(i);
}
function updateScore() {
  scoreEl.textContent = 'X 胜 ' + score.X + ' ｜ 平局 ' + score.D + ' ｜ O 胜 ' + score.O;
}
function place(i) {
  if (over || state[i]) return;
  state[i] = turn;
  marks[i].textContent = turn;
  marks[i].setAttribute('fill', turn === 'X' ? '#38bdf8' : '#f472b6');
  var win = null;
  for (var j = 0; j < LINES.length; j++) {
    var L = LINES[j];
    if (state[L[0]] && state[L[0]] === state[L[1]] && state[L[1]] === state[L[2]]) { win = L; break; }
  }
  if (win) {
    over = true;
    score[turn]++;
    var a = center(win[0]), b = center(win[2]);
    winline.setAttribute('x1', a[0]); winline.setAttribute('y1', a[1]);
    winline.setAttribute('x2', b[0]); winline.setAttribute('y2', b[1]);
    winline.setAttribute('visibility', 'visible');
    for (var k = 0; k < 3; k++) cells[win[k]].setAttribute('fill', '#31415e');
    statusEl.textContent = turn + ' 获胜！';
    statusEl.setAttribute('fill', '#facc15');
  } else if (state.every(function (v) { return v; })) {
    over = true; score.D++;
    statusEl.textContent = '平局';
    statusEl.setAttribute('fill', '#94a3b8');
  } else {
    turn = turn === 'X' ? 'O' : 'X';
    statusEl.textContent = '轮到 ' + turn + ' 落子';
  }
  updateScore();
}
function reset() {
  state = ['', '', '', '', '', '', '', '', ''];
  turn = 'X'; over = false;
  for (var i = 0; i < 9; i++) {
    marks[i].textContent = '';
    marks[i].setAttribute('fill', 'transparent');
    cells[i].setAttribute('fill', '#1e293b');
  }
  winline.setAttribute('visibility', 'hidden');
  statusEl.textContent = '轮到 X 落子';
  statusEl.setAttribute('fill', '#f8fafc');
}
document.getElementById('restart').addEventListener('click', reset);
reset();
